arguments.command:
cd /workspace/submission && python3 - << 'PY'
src=open('engine.hpp').read()
src=src.replace("""    startAt.assign(n ? pts.size() : 1, {});
    endAt.assign(pts.size(), {});""",
"""    startAt.assign(pts.size(), {});
    endAt.assign(pts.size(), {});""")
src=src.replace("""// Maximal forwarding runs: unique starts, coalesced equal next hops.""",
"""// Maximal forwarding runs of one RIB version: unique starts, strictly
// increasing, always beginning at zero, with adjacent equal next hops
// coalesced.  Boundaries are every route start plus every route end below
// the domain end; the longest active prefix decides each elementary
// interval, so a withdrawn route reveals its covering fallback.""")
open('engine.hpp','w').write(src)
PY
g++ -O2 -std=c++17 engine.cpp -o /workspace/tmp/engine && echo BUILD_OK && cd /workspace/examples && for f in *.in.native; do
  /workspace/tmp/engine < $f > /tmp/out.txt 2>/tmp/err.txt
  if diff ${f/.in./.out.} /tmp/out.txt > /dev/null; then echo "PASS $f"; else echo "FAIL $f"; fi
done; cd /workspace && python3 -B /tmp/runcheck.py
